from collections import Counter, deque

def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    counts=Counter(v for row in grid for v in row if v!=0)
    border=counts.most_common(1)[0][0]
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if not v or v==border or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); pts=[]
            while q:
                y,x=q.pop(); pts.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==v:
                        seen.add((yy,xx)); q.append((yy,xx))
            rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
            comps.append((v,min(rs),max(rs),min(cs),max(cs)))
    for i,a in enumerate(comps):
        v,r0,r1,c0,c1=a
        for b in comps[i+1:]:
            vb,s0,s1,d0,d1=b
            if vb!=v: continue
            if (r0,r1)==(s0,s1):
                left,right=sorted(((c0,c1),(d0,d1)))
                for y in range(r0,r1+1):
                    for x in range(left[1]+1,right[0]):
                        if grid[y][x]==0: out[y][x]=v
            if (c0,c1)==(d0,d1):
                top,bot=sorted(((r0,r1),(s0,s1)))
                for x in range(c0,c1+1):
                    for y in range(top[1]+1,bot[0]):
                        if grid[y][x]==0: out[y][x]=v
    return out

