program='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row if v != 0)
    border = counts.most_common(1)[0][0]
    seen = set()
    components = []
    marker_counts = Counter()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or color == border or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                            (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            marker_counts[color] += len(cells)
            rows = [y for y, _ in cells]
            cols = [x for _, x in cells]
            components.append((color, min(rows), max(rows), min(cols), max(cols)))
    default = marker_counts.most_common(1)[0][0]
    for i, (color, r0, r1, c0, c1) in enumerate(components):
        if color == default:
            continue
        for other, s0, s1, d0, d1 in components[i + 1:]:
            if other != color:
                continue
            if (r0, r1) == (s0, s1):
                left, right = sorted(((c0, c1), (d0, d1)))
                for y in range(r0, r1 + 1):
                    for x in range(left[1] + 1, right[0]):
                        if grid[y][x] == 0:
                            out[y][x] = color
            if (c0, c1) == (d0, d1):
                top, bottom = sorted(((r0, r1), (s0, s1)))
                for x in range(c0, c1 + 1):
                    for y in range(top[1] + 1, bottom[0]):
                        if grid[y][x] == 0:
                            out[y][x] = color
    return out
'''
